// Author: MiYu. Focused real-session checks for nested AI pause, guard isolation and paid replacement requests.
#include "session.h"
#include "setup.h"
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=3)throw std::runtime_error("Usage: war3_ai_control_tests <data-root> <control-fixture>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());setup.control(1,SlotControl::ComputerNormal);session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto& a=*session.ais()[0]->runtime;auto& b=*session.ais()[1]->runtime;unsigned passed=0;auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto call=[](jass::Runtime& runtime,const char* name,std::initializer_list<jass::Value> args){return runtime.invoke(name,{args.begin(),args.size()});};auto p0=call(vm,"Player",{vm.integer(0)});auto type=ObjectData::code("hfoo");auto first=vm.global("first"),free=vm.global("free0");
        session.advance(.125);auto before=a.global("pulses").bits;require(before>0 && b.global("pulses").bits==before,"Source pulse did not run independently");call(vm,"PauseCompAI",{p0,vm.boolean(true)});call(vm,"PauseCompAI",{p0,vm.boolean(true)});session.advance(.5);require(a.global("pulses").bits==before && b.global("pulses").bits>before,"Player pause blocked another AI or resumed its own thread");call(vm,"PauseCompAI",{p0,vm.boolean(false)});session.advance(.125);require(a.threadsPaused() && a.global("pulses").bits==before,"Nested AI pause was released too soon");call(vm,"PauseCompAI",{p0,vm.boolean(false)});session.advance(.09375);require(a.global("pulses").bits==before,"Pause discarded remaining script sleep");session.advance(.03125);require(a.global("pulses").bits==before+1 && !a.threadsPaused(),"AI pause did not resume after the remaining wait");call(vm,"PauseCompAI",{p0,vm.boolean(false)});require(a.threadsPaused(),"Original nonzero pause count was clamped");call(vm,"PauseCompAI",{p0,vm.boolean(true)});require(!a.threadsPaused(),"Balanced signed-wrap pause count did not resume");++passed;std::cout<<"PASS player_pause_counts_and_isolation\n";
        require(call(a,"IgnoredUnits",{a.integer(int(type))}).bits==1 && call(b,"IgnoredUnits",{b.integer(int(type))}).bits==1,"Guard posts did not reserve actual owned units");call(vm,"SetUnitCreepGuard",{first,vm.boolean(true)});require(session.units().at(first.bits)->creepGuard,"Source creep guard flag was not applied");call(vm,"SetUnitCreepGuard",{first,vm.boolean(false)});require(!session.units().at(first.bits)->creepGuard,"Source creep guard flag did not clear");call(vm,"UnitApplyTimedLife",{free,vm.integer(int(ObjectData::code("BTLF"))),vm.real(jass::Real::fromInteger(5))});call(a,"GroupTimedLife",{a.boolean(false)});require(call(a,"IgnoredUnits",{a.integer(int(type))}).bits==2 && !call(a,"AddAssault",{a.integer(1),a.integer(int(type))}).bits,"Timed or guarded units entered assault");call(a,"GroupTimedLife",{a.boolean(true)});require(call(a,"AddAssault",{a.integer(1),a.integer(int(type))}).bits,"Released timed units were unavailable to assault");call(vm,"RemoveGuardPosition",{first});require(!call(a,"IgnoredUnits",{a.integer(int(type))}).bits,"Guard removal left a reserved unit");call(vm,"RecycleGuardPosition",{first});require(call(a,"IgnoredUnits",{a.integer(int(type))}).bits==1 && session.units().at(first.bits)->guardHome.has_value(),"Recycled guard was not registered");auto p1=call(vm,"Player",{vm.integer(1)});call(vm,"SetUnitOwner",{first,p1,vm.boolean(false)});require(!session.units().at(first.bits)->guardHome && !call(a,"IgnoredUnits",{a.integer(int(type))}).bits && call(b,"IgnoredUnits",{b.integer(int(type))}).bits==1,"Ownership transfer retained an old guard reservation");call(vm,"SetUnitOwner",{first,p0,vm.boolean(false)});call(vm,"RecycleGuardPosition",{first});call(vm,"RemoveAllGuardPositions",{p0});require(!call(a,"IgnoredUnits",{a.integer(int(type))}).bits && call(b,"IgnoredUnits",{b.integer(int(type))}).bits==1 && session.units().size()==4,"Guard removal leaked across players or created free units");++passed;std::cout<<"PASS guard_and_timed_life_reservations\n";
        call(vm,"RecycleGuardPosition",{first});auto barracks=call(vm,"CreateUnit",{p0,vm.integer(int(ObjectData::code("hbar"))),vm.real(jass::Real::fromInteger(-1024)),vm.real(jass::Real::fromInteger(0)),vm.real(jass::Real::fromInteger(0))});for(auto [state,value]:std::initializer_list<std::pair<int,int>>{{1,1000},{2,1000},{4,100},{6,100}})call(vm,"SetPlayerState",{p0,vm.handle("playerstate",unsigned(state)),vm.integer(value)});auto gold=session.config().players[0].states.at(1);auto cost=call(a,"GetUnitGoldCost",{a.integer(int(type))}).bits;call(a,"AddGuardPost",{a.integer(int(type)),a.real(jass::Real::fromInteger(-768)),a.real(jass::Real::fromInteger(0))});call(a,"FillGuardPosts",{});auto factory=session.units().at(barracks.bits);require(factory->production.size()==1 && factory->production.front().type==type && session.config().players[0].states.at(1)==gold-int(cost) && session.units().size()==5,"Missing guard was not recruited through the paid queue");++passed;std::cout<<"PASS paid_guard_recruitment\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed="<<passed<<" failed=0\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
